`timescale 1ns/1ps
// HBM-FORM-SPLIT-8+REFORM-B11 (glue_d15r RE-FORM): PORT-CUT copies of the VMS glue submodules for the 3-piece split of
// hfd_hgi_vms_glue_nw_t.  GENERATED by results/die_hbm_1105/form_split/glue_b11/mk_pc.py from the rtl/hbm_accel/generic/vm/static
// sources.  On every port that crosses between split pieces the boundary register is removed (an input register becomes a
// wire, an output register becomes its combinational next value), so the two kit face flops of a crossing (+1 out, +1 in)
// take the place of the two registers it had (producer output reg + consumer input reg): 0 added cycles on every crossing.
// Only crossing ports change; die-facing ports keep their registers.  The cut regs only reset to the values their sources
// already hold in reset (valid state resets), so the unreset face flops flush within 2 reset edges (reset contract 64).
// DMUT (bench mutants): 1 rstop keeps the ri input reg (+1); 2 status takes the ring fault at the flags stage (+2);
// 3 hub keeps the cco input regs (+1); 4 rcl inverts the ri return port.
`default_nettype none
// Compiler scheduled successor of the historical B2 ring stop. The flit ABI
// stays 2224 bits. Every injected, forwarded, replayed and committed beat has
// an assigned cycle; there are no credits, queues, retries or dynamic picks.
// tx source 0 transit, 1 hub PREQ, 2 bank mirror egress, 3 replay PRSP,
// 4 opposite-stop WACK. A local eject and transit may share the same cycle.
module ot_vms_rstop_static_pc #(
    parameter integer DMUT=0,
    parameter integer PHYSICAL_RING=1,
    parameter integer COMMIT_DELAY=5,
    parameter integer MUT=0
) (
    input wire clk, rst_n,
    input wire [1:0] sid,
    input wire dir,
    input wire tx_enable,
    input wire [2:0] tx_source,
    input wire [2223:0] l_in,
    output reg [2223:0] l_out,
    input wire [289:0] pi,
    input wire [8*276-1:0] eg,
    output reg [8*276-1:0] xq,
    input wire [7:0] xq_done,
    output reg [287:0] rce,
    input wire [265:0] ri,
    output reg [2:0] wko,
    input wire [2:0] wki,
    output reg [263:0] cco,
    output reg ack_o,
    input wire ack_i,
    output reg mirror_busy,
    output reg fault
);
    reg [2223:0] in_q;
    wire [289:0] pi_q=pi;                      // crossing input (hub): kit face flop
    reg [2207:0] eg_q;
    reg [265:0] ri_r;
    wire [265:0] ri_q=(DMUT==1)?ri_r:ri;       // crossing input (replay)
    always @(posedge clk) ri_r<=ri;
    wire [2:0] wki_q=wki;                      // crossing input (opposite stop)
    reg [2:0] source_q;
    reg enable_q;
    reg [1:0] me;
    reg dr;
    wire ack_q=ack_i;                          // crossing input (opposite stop)
    reg [COMMIT_DELAY-1:0] commit_v;
    reg [7:0] commit_mask [0:COMMIT_DELAY-1];
    reg [1:0] commit_src [0:COMMIT_DELAY-1];
    reg [15:0] outstanding;
    wire [1:0] kind=in_q[2222:2221];
    wire own=in_q[2223] && in_q[2217+int'(me)];
    wire [3:0] rest=in_q[2220:2217] & ~(4'b1 << me);
    wire transit=in_q[2223] && (|rest);
    reg [7:0] lanes, ev;
    reg [2:0] bank;
    reg [274:0] lane;
    reg [2223:0] flit;
    reg [3:0] dest;
    wire [1:0] rank={me[1],me[1]^me[0]};
    wire [1:0] r1=rank+2'd1, r2=rank+2'd2, r3=rank+2'd3;
    wire [1:0] d1=(PHYSICAL_RING!=0) ? {r1[1],r1[1]^r1[0]} : me+2'd1;
    wire [1:0] d2=(PHYSICAL_RING!=0) ? {r2[1],r2[1]^r2[0]} : me+2'd2;
    wire [1:0] d3=(PHYSICAL_RING!=0) ? {r3[1],r3[1]^r3[0]} : me+2'd3;
    always @* begin
        lanes='0; ev='0; bank='0; lane='0;
        for(integer b=0;b<8;b=b+1) begin
            lanes[b]=in_q[b*276+275]; ev[b]=eg_q[b*276+275];
            if(lanes[b]) begin bank=3'(b); lane=lane | in_q[b*276+:275]; end
        end
        dest=dr ? (4'b1 << d3) : ((4'b1 << d1)|(4'b1 << d2));
        flit='0;
        if(enable_q) case(source_q)
            0: begin flit=in_q; flit[2223]=transit; flit[2220:2217]=rest; end
            1: begin
                flit[2223]=pi_q[289]; flit[2222:2221]=0;
                flit[2220:2217]=pi_q[288:285]; flit[2216:2215]=me;
                flit[2214:2211]=pi_q[284:281]; flit[2210:2209]=pi_q[280:279]; flit[2208]=pi_q[278];
                for(integer b=0;b<8;b=b+1) if(pi_q[277:275]==3'(b))
                    flit[b*276+:276]={1'b1,pi_q[274:264],pi_q[255:0],pi_q[263:256]};
            end
            2: begin flit[2223]=|ev; flit[2222:2221]=1; flit[2220:2217]=dest;
                flit[2216:2215]=me; flit[2207:0]=eg_q; end
            3: begin flit[2223]=ri_q[265]; flit[2222:2221]=2;
                flit[2220:2217]=4'b1<<ri_q[264:263]; flit[2216:2215]=me;
                flit[2214:2211]=ri_q[262:259]; flit[2210:2209]=ri_q[258:257];
                flit[2208]=ri_q[256]; flit[263:8]=ri_q[255:0]; end
            4: begin flit[2223]=wki_q[2]; flit[2222:2221]=3;
                flit[2220:2217]=4'b1<<wki_q[1:0]; flit[2216:2215]=me; end
            default: flit='0;
        endcase
        if(MUT==1 && flit[2223] && flit[2222:2221]==1) flit[8]=~flit[8];
    end
    // Crossing outputs (replay rce, hub cco, opposite stop wko / ack_o): the next value of the cut output register.
    always @* begin
        rce='0; cco='0; ack_o=1'b0; wko='0;
        if(own) case(kind)
            0: rce={1'b1,in_q[2216:2215],in_q[2214:2211],in_q[2210:2209],in_q[2208],bank,lane[274:264],lane[7:0],lane[263:8]};
            2: cco={1'b1,in_q[2214:2211],in_q[2210:2209],in_q[2208],in_q[263:8]};
            3: ack_o=1'b1;
            default: ;
        endcase
        if(commit_v[COMMIT_DELAY-1] && (xq_done & commit_mask[COMMIT_DELAY-1]) == commit_mask[COMMIT_DELAY-1])
            wko={1'b1,commit_src[COMMIT_DELAY-1]};
    end
    // Only valid state resets. Die-facing outputs are registered face pins.
    always @(posedge clk or negedge rst_n) begin
        if(!rst_n) begin
            in_q<='0;eg_q<='0;
            source_q<=0;enable_q<=0;me<=0;dr<=0;
            l_out<='0;xq<='0;
            commit_v<='0;outstanding<=0;mirror_busy<=0;fault<=0;
            for(integer t=0;t<COMMIT_DELAY;t=t+1) begin commit_mask[t]<=0;commit_src[t]<=0;end
        end else begin
            in_q<=l_in;eg_q<=eg;
            source_q<=tx_source;enable_q<=tx_enable;me<=sid;dr<=dir;
            l_out<=flit;
            xq<='0;
            if(own) case(kind)
                0: begin
                    if($countones(lanes)!=1) fault<=1;
                end
                1: xq<=in_q[2207:0];
                default: ;
            endcase
            // The compiler cannot silently discard any arriving work.
            if((transit && (!enable_q || source_q!=0)) ||
               (pi_q[289] && (!enable_q || source_q!=1)) ||
               ((|ev) && (!enable_q || source_q!=2)) ||
               (ri_q[265] && (!enable_q || source_q!=3)) ||
               (wki_q[2] && (!enable_q || source_q!=4)) ||
               (enable_q && source_q>4) ||
               (in_q[2223] && in_q[2220:2217]==0)) fault<=1;
            commit_v[0]<=own && kind==1;
            commit_mask[0]<=lanes;commit_src[0]<=in_q[2216:2215];
            for(integer t=1;t<COMMIT_DELAY;t=t+1) begin
                commit_v[t]<=commit_v[t-1];commit_mask[t]<=commit_mask[t-1];commit_src[t]<=commit_src[t-1];
            end
            if(commit_v[COMMIT_DELAY-1]) begin
                if((xq_done & commit_mask[COMMIT_DELAY-1]) != commit_mask[COMMIT_DELAY-1]) fault<=1;
            end
            // Outstanding is observation only: it never gates any datapath.
            outstanding<=outstanding + ((flit[2223] && source_q==2)?(dr?16'd1:16'd2):16'd0) - (ack_q?16'd1:16'd0);
            mirror_busy<=outstanding!=0;
            if(ack_q && outstanding==0) fault<=1;
        end
    end
endmodule
// Static successor to b2/ot_vms_hub. Historical credit tile is unchanged.
// NC local clients plus client NC for replay from the VM ring. Compiler selects
// a client independently for each bank and each ring direction, on the SAME
// edge as cq and client_seq. There is no pending-request storage or arbitration.
// cq338={v,we,addr32,data256,byte_mask32,tag16}; cr274={v,tag16,we,data256}.
// pq285={v,we,rowm11,data256,wordmask8,tag8}; pr266={v,we,tag8,data256}.
// Bank tag={client4,00,seq2}; PREQ290={v,dmask4,client4,seq2,we,bank3,
// rowm11,wmask8,data256}; PRSP264={v,client4,seq2,we,data256}.
// Requests and responses each take TWO edges through pin/output registers.
// Four tag slots per client are compiler allocated, never used for admission.
// Compiler must issue every piece of a packet together, reserve its slot until
// return, preserve client request/response order, and avoid multiple completed
// transactions for a client on one edge.
// Native mirror writes issue local+CW(next,opposite)+CCW(previous); all four
// acknowledgements must precede the compiler response calendar. Missing ones
// fault at that edge; they never delay or replay cr. Replay never rebroadcasts.
// status sticky {range/address fault, byte-mask fault, schedule/identity fault}.
module ot_vms_hub_static_pc #(
    parameter integer DMUT=0,
    parameter integer NC=4,
    parameter integer PHYSICAL_RING=1,
    parameter integer CW=(NC<1)?1:$clog2(NC+1),
    parameter integer MUT=0 // 1 wrong bank; 2 wrong tag; 3 ignores select; 4 waits for missing ack
)(
    input wire clk, rst_n,
    input wire [1:0] sid,
    input wire [(NC+1)*338-1:0] cq,
    input wire [(NC+1)*2-1:0] client_seq,
    input wire [7:0] bank_enable,
    input wire [8*CW-1:0] bank_client,
    input wire cw_enable,
    input wire [CW-1:0] cw_client,
    input wire ccw_enable,
    input wire [CW-1:0] ccw_client,
    output wire [(NC+1)*274-1:0] cr,
    output wire [8*285-1:0] pq,
    input wire [8*266-1:0] pr,
    output wire [289:0] cwi, cci,
    input wire [263:0] cco0, cco1,
    input wire [NC:0] response_enable,
    input wire [(NC+1)*2-1:0] response_seq,
    output reg [2:0] status
);
    localparam integer N=NC+1;
    reg [N*338-1:0] qr;
    reg [N*2-1:0] sq;
    reg [7:0] be;
    reg [8*CW-1:0] bc;
    reg ce, cce;
    reg [CW-1:0] cs, ccs;
    reg [1:0] me;
    reg [8*266-1:0] br;
    reg [263:0] rr0_r,rr1_r;
    wire [263:0] rr0=(DMUT==3)?rr0_r:cco0, rr1=(DMUT==3)?rr1_r:cco1;   // crossing inputs (ring stops)
    reg [N-1:0] re;
    reg [N*2-1:0] rseq;
    reg [255:0] response_data[0:N-1][0:3];
    reg [15:0] tags[0:N-1][0:3];
    reg active[0:N-1][0:3], writes[0:N-1][0:3];
    reg [2:0] expected[0:N-1][0:3], seen[0:N-1][0:3];
    reg [2:0] arrivals[0:N-1][0:3];
    reg [255:0] returned_data[0:N-1][0:3];
    reg [N*274-1:0] cr_next;
    reg [8*285-1:0] pq_next;
    reg [289:0] cw_next,ccw_next;
    reg [2:0] fault;
    reg [N*274-1:0] cr_payload;
    reg [8*285-1:0] pq_payload;
    reg [288:0] cw_payload,ccw_payload;
    reg [N-1:0] cr_valid;
    reg [7:0] pq_valid;
    reg cw_valid,ccw_valid;
    for(genvar g=0;g<N;g=g+1) begin : client_output
        assign cr[g*274+:274]={cr_valid[g],cr_payload[g*274+:273]};
    end
    for(genvar g=0;g<8;g=g+1) begin : bank_output
        assign pq[g*285+:285]={pq_valid[g],pq_payload[g*285+:284]};
    end
    assign cwi=cw_next;                        // crossing outputs (ring stops): next value of the cut regs
    assign cci=ccw_next;
    always @(posedge clk) begin
        cr_payload<=cr_next; pq_payload<=pq_next;
        cw_payload<=cw_next[288:0]; ccw_payload<=ccw_next[288:0];
    end
    reg [N-1:0] issued_local,issued_cw,issued_ccw;
    wire [1:0] rank={me[1],me[1]^me[0]};
    wire [1:0] nr=rank+2'd1, orank=rank+2'd2, pvr=rank+2'd3;
    wire [1:0] next_sid=(PHYSICAL_RING!=0)?{nr[1],nr[1]^nr[0]}:me+2'd1;
    wire [1:0] opposite_sid=(PHYSICAL_RING!=0)?{orank[1],orank[1]^orank[0]}:me+2'd2;
    wire [1:0] previous_sid=(PHYSICAL_RING!=0)?{pvr[1],pvr[1]^pvr[0]}:me+2'd3;
    wire [3:0] cw_dest=(4'b1<<next_sid)|(4'b1<<opposite_sid);
    wire [3:0] ccw_dest=4'b1<<previous_sid;
    function automatic [2:0] bank_of(input [337:0] q);
        bank_of=(MUT==1)?q[312:310]:q[311:309];
    endfunction
    function automatic [7:0] wordmask(input [337:0] q);
        for(integer w=0;w<8;w=w+1) wordmask[w]=&q[16+4*w+:4];
    endfunction
    function automatic local_needed(input [337:0] q,input integer c);
        local_needed=(c==NC)||q[324]||(q[323:322]==me);
    endfunction
    function automatic cw_needed(input [337:0] q,input integer c);
        cw_needed=(c!=NC)&&((q[324]&&q[336])||(!q[324]&&((4'b1<<q[323:322])&cw_dest)!=0));
    endfunction
    function automatic ccw_needed(input [337:0] q,input integer c);
        ccw_needed=(c!=NC)&&((q[324]&&q[336])||(!q[324]&&q[323:322]==previous_sid));
    endfunction
    // Every pin payload is captured; only validity/control flops reset.
    always @(posedge clk) begin
        qr<=cq; sq<=client_seq; bc<=bank_client; cs<=cw_client;
        ccs<=ccw_client; me<=sid; br<=pr; rr0_r<=cco0; rr1_r<=cco1; rseq<=response_seq;
    end
    // Mask pin valid bits independently of payload reset.
    reg [N-1:0] qvalid;
    reg [7:0] bvalid;
    reg rv0_r,rv1_r;
    wire rvalid0=(DMUT==3)?rv0_r:cco0[263], rvalid1=(DMUT==3)?rv1_r:cco1[263];
    always @(posedge clk or negedge rst_n) begin
        if(!rst_n) begin
            qvalid<='0; bvalid<='0; rv0_r<=0; rv1_r<=0;
            be<=0; ce<=0; cce<=0; re<=0;
        end else begin
            for(integer c=0;c<N;c=c+1) qvalid[c]<=cq[c*338+337];
            for(integer b=0;b<8;b=b+1) bvalid[b]<=pr[b*266+265];
            rv0_r<=cco0[263]; rv1_r<=cco1[263];
            be<=bank_enable; ce<=cw_enable; cce<=ccw_enable; re<=response_enable;
        end
    end
    always @* begin : route
        integer c,k,b,rc,rs,completed;
        reg [337:0] q;
        reg [3:0] mask;
        reg [263:0] rp;
        reg [7:0] wm;
        fault=0; pq_next=0; cw_next=0; ccw_next=0; cr_next=0;
        issued_local=0; issued_cw=0; issued_ccw=0;
        q=0; mask=0; rp=0; wm=0; c=0; k=0; rc=0; rs=0; completed=0;
        for(b=0;b<8;b=b+1) if(be[b]) begin
            c=(MUT==3)?0:int'(bc[b*CW+:CW]);
            if(c>=N) fault[0]=1;
            else begin
                q=qr[c*338+:338];
                if(!qvalid[c]||!local_needed(q,c)||bank_of(q)!=3'(b)) fault[0]=1;
                else begin
                    pq_next[b*285+:285]={1'b1,q[336],q[324],q[321:312],q[303:48],wordmask(q),4'(c),2'b00,sq[c*2+:2]};
                    if(issued_local[c]) fault[0]=1;
                    issued_local[c]=1;
                end
            end
        end
        for(integer dir=0;dir<2;dir=dir+1) if(dir==0?ce:cce) begin
            c=dir==0?int'(cs):int'(ccs);
            if(c>=N) fault[0]=1;
            else begin
                q=qr[c*338+:338];
                if(!qvalid[c]||!(dir==0?cw_needed(q,c):ccw_needed(q,c))) fault[0]=1;
                else begin
                    mask=q[324]?(dir==0?cw_dest:ccw_dest):(4'b1<<q[323:322]);
                    rp=0;
                    if(dir==0) begin
                        cw_next={1'b1,mask,4'(c),sq[c*2+:2],q[336],bank_of(q),q[324],q[321:312],wordmask(q),q[303:48]};
                        issued_cw[c]=1;
                    end else begin
                        ccw_next={1'b1,mask,4'(c),sq[c*2+:2],q[336],bank_of(q),q[324],q[321:312],wordmask(q),q[303:48]};
                        issued_ccw[c]=1;
                    end
                end
            end
        end
        for(c=0;c<N;c=c+1) if(qvalid[c]) begin
            q=qr[c*338+:338]; k=int'(sq[c*2+:2]); wm=wordmask(q);
            if(active[c][k]) fault[0]=1;
            if(issued_local[c]!=local_needed(q,c)||issued_cw[c]!=cw_needed(q,c)||issued_ccw[c]!=ccw_needed(q,c)) fault[0]=1;
            if(q[335:325]!=0||q[308:304]!=0||(q[324]&&q[323:322]!=0)||(c==NC&&!q[324]&&q[323:322]!=me)) fault[2]=1;
            for(integer w=0;w<8;w=w+1) if(q[336]&&q[16+4*w+:4]!={4{wm[w]}}) fault[1]=1;
        end
        for(c=0;c<N;c=c+1) for(k=0;k<4;k=k+1) begin arrivals[c][k]=0; returned_data[c][k]=0; end
        // Tag-decode demultiplex only; no response priority or ready signals.
        for(b=0;b<10;b=b+1) begin
            if(b<8) begin
                rc=int'(br[b*266+260+:4]); rs=int'(br[b*266+256+:2]);
                rp={bvalid[b],br[b*266+260+:4],br[b*266+256+:2],br[b*266+264],br[b*266+:256]};
                if(bvalid[b]&&br[b*266+258+:2]!=0) fault[0]=1;
            end else begin
                rp=b==8?{rvalid0,rr0[262:0]}:{rvalid1,rr1[262:0]};
                rc=int'(rp[262:259]); rs=int'(rp[258:257]);
            end
            if(rp[263]) begin
                if(rc>=N) fault[0]=1;
                else begin
                    if(!active[rc][rs]||writes[rc][rs]!=rp[256]) fault[0]=1;
                    arrivals[rc][rs]=arrivals[rc][rs]+3'd1;
                    returned_data[rc][rs]=returned_data[rc][rs]|rp[255:0];
                end
            end
        end
        for(c=0;c<N;c=c+1) begin
            for(k=0;k<4;k=k+1) if(arrivals[c][k]!=0)
                if({1'b0,seen[c][k]}+{1'b0,arrivals[c][k]}>{1'b0,expected[c][k]}) fault[0]=1;
            // A compiler calendar entry emits on its assigned edge, even on a
            // missing-ack fault. There is no completion-driven release path.
            if(re[c]&&(MUT!=4||seen[c][rseq[c*2+:2]]+arrivals[c][rseq[c*2+:2]]==expected[c][rseq[c*2+:2]])) begin
                k=int'(rseq[c*2+:2]);
                if(!active[c][k]||{1'b0,seen[c][k]}+{1'b0,arrivals[c][k]}!={1'b0,expected[c][k]}) fault[0]=1;
                cr_next[c*274+:274]={1'b1,(MUT==2?tags[c][k]^16'd1:tags[c][k]),writes[c][k],
                    writes[c][k]?256'd0:(response_data[c][k]|returned_data[c][k])};
            end
        end
    end
    always @(posedge clk or negedge rst_n) begin : state
        if(!rst_n) begin
            pq_valid<=0; cr_valid<=0; cw_valid<=0; ccw_valid<=0; status<=0;
            for(integer c=0;c<N;c=c+1) for(integer k=0;k<4;k=k+1) begin
                active[c][k]<=0; seen[c][k]<=0; expected[c][k]<=0; writes[c][k]<=0;
            end
        end else begin
            for(integer b=0;b<8;b=b+1) pq_valid[b]<=pq_next[b*285+284];
            for(integer c=0;c<N;c=c+1) cr_valid[c]<=cr_next[c*274+273];
            cw_valid<=cw_next[289]; ccw_valid<=ccw_next[289];
            status<=status|fault;
            for(integer c=0;c<N;c=c+1) begin
                for(integer k=0;k<4;k=k+1) if(arrivals[c][k]!=0) begin
                    seen[c][k]<=seen[c][k]+arrivals[c][k];

                end
                if(re[c]) active[c][rseq[c*2+:2]]<=0;
                if(qvalid[c]) begin
                    active[c][sq[c*2+:2]]<=1;
                    seen[c][sq[c*2+:2]]<=0;
                    expected[c][sq[c*2+:2]]<=(qr[c*338+324]&&qr[c*338+336]&&c!=NC)?3'd4:3'd1;
                    writes[c][sq[c*2+:2]]<=qr[c*338+336];
                end
            end
        end
    end
    always @(posedge clk) for(integer c=0;c<N;c=c+1) begin
        for(integer k=0;k<4;k=k+1) if(arrivals[c][k]!=0)
            response_data[c][k]<=response_data[c][k]|returned_data[c][k];
        if(qvalid[c]) begin
            tags[c][sq[c*2+:2]]<=qr[c*338+:16];
            response_data[c][sq[c*2+:2]]<=0;
        end
    end
endmodule
// Fixed cycle ring packet replay. The returned packet tag itself carries the
// return route; no FIFO, lease, response credit or arrival arbitration exists.
module ot_vms_rcl_static_pc #(parameter integer MUT=0, parameter integer DMUT=0) (
    input wire clk,rst_n,
    input wire [1:0] sid,
    input wire rx_enable,rx_source,
    input wire [287:0] rce0,rce1,
    output reg [337:0] hq,
    input wire [273:0] hr,
    output reg [265:0] ri0,ri1,
    output reg fault
);
    wire [287:0] a=rce0, b=rce1;               // crossing inputs (ring stops)
    reg [273:0] response;
    reg [1:0] me;
    reg select_q,enable_q;
    wire [287:0] e=select_q?b:a;
    wire [14:0] sec={e[274]?2'b00:me,e[273:264],e[277:275]};
    wire [31:0] addr={11'b0,e[274],sec,5'b0};
    wire [15:0] tag={6'b0,~select_q,e[286:285],e[284:281],e[280:279],e[278]};
    wire return_port=response[266] ^ (MUT==1);
    reg [31:0] mask;
    always @* for(integer k=0;k<8;k=k+1) mask[k*4+:4]={4{e[256+k]}};
    // Crossing outputs (ring stops): next value of the cut ri registers (response resets, so ri is 0 in reset).
    wire rp=return_port ^ (DMUT==4);
    always @* begin
        ri0={response[273] && !rp,response[265:264],response[263:260],response[259:258],response[256],response[255:0]};
        ri1={response[273] && rp,response[265:264],response[263:260],response[259:258],response[256],response[255:0]};
    end
    always @(posedge clk or negedge rst_n)
        if(!rst_n) begin
            response<=0;me<=0;select_q<=0;enable_q<=0;
            hq<=0;fault<=0;
        end else begin
            // HBM-CORES-KITS-5 10-28: response[272:267] are the reserved upper tag bits. They are this module's own
            // constant 0 (hq tag = {6'b0,...}) returned through the hub's UNRESET tag store, so the old reserved-bit
            // check could only ever see the power-up X of a never-written hub slot; synthesis removed that X chain
            // (vms_glue _k6 kit LEC NOT EQUIVALENT, u_replay.fault).  They are captured as the defined constant 0, as the
            // synthesised netlist already does.  An emit from an inactive hub slot still faults in the hub (status[0]).
            response<={hr[273],6'b0,hr[266:0]};me<=sid;
            select_q<=rx_source;enable_q<=rx_enable;
            hq<={enable_q && e[287],e[278],addr,e[255:0],mask,tag};
            if((a[287] && (!enable_q || select_q)) ||
               (b[287] && (!enable_q || !select_q))) fault<=1;
        end
endmodule
// Real status producer for command processor vmstat19. Three balanced adder
// rungs saturate the eight bank CE counters; all faults follow the same delay.
module ot_vms_status_static_pc #(parameter integer DMUT=0) (
    input wire clk,rst_n,
    input wire [143:0] bank_status,
    input wire [2:0] hub_status,
    input wire ring_fault,       // same-piece fault (replay), flags stage as before
    input wire ring_fault_late,  // ring stop faults over a crossing: 2 face edges late = the flags1 stage
    output reg [18:0] vmstat
);
    reg [16:0] pair_sum[0:3];
    reg [17:0] half_sum[0:1];
    reg [2:0] flags0,flags1;
    reg [1:0] sum_valid;
    wire [18:0] total={1'b0,half_sum[0]}+{1'b0,half_sum[1]};
    reg [2:0] flags;
    always @* begin
        flags={hub_status[2]|hub_status[0]|ring_fault|(DMUT==2 && ring_fault_late),hub_status[1],1'b0};
        for(integer b=0;b<8;b=b+1)begin
            flags[2]=flags[2]|bank_status[b*18+17];
            flags[0]=flags[0]|bank_status[b*18+16];
        end
    end
    always @(posedge clk)begin
        for(integer i=0;i<4;i=i+1)
            pair_sum[i]<={1'b0,bank_status[(i*2)*18+:16]}+{1'b0,bank_status[(i*2+1)*18+:16]};
        half_sum[0]<={1'b0,pair_sum[0]}+{1'b0,pair_sum[1]};
        half_sum[1]<={1'b0,pair_sum[2]}+{1'b0,pair_sum[3]};
    end
    always @(posedge clk or negedge rst_n)
        if(!rst_n)begin flags0<=0;flags1<=0;sum_valid<=0;vmstat<=0;end
        else begin
            flags0<=flags;flags1<=flags0;sum_valid<={sum_valid[0],1'b1};
            vmstat<=sum_valid[1]?{flags1|{DMUT!=2 && ring_fault_late,2'b0},(|total[18:16])?16'hffff:total[15:0]}:19'd0;
        end
endmodule
`default_nettype wire
